\label{thm:intro-boolean}
Let \(P\) be a finite poset with $|P|\ge 2$.
\begin{enumerate}[label=(\roman*), font=\upshape]
\item If $P$ admits an AHP, then $P\times B_r$ admits an AHC for every $r\ge2$.
\item If $P$ admits an AHC, then $P\times B_r$ admits an AHP for every $r\ge0$.
\end{enumerate}

\label{thm:intro-products}
For a positive integer $n$, let $D_n$ be the divisor lattice. Then 
\begin{enumerate}[label=(\roman*), font=\upshape]
\item $D_n$ admits an AHP.
\item $D_n$ admits an AHC if and only if $|D_n|$ is even, $D_n\ncong C_1$ and $D_n\ncong B_2$.
\end{enumerate}

\label{lem:b2}
Let $P$ be a finite poset with $|P|\ge 2$.
If $P$ admits an AHP, then $P\times B_2$ admits an AHC.

If $|P|=2$, then $P\cong B_1$ is a two-element chain and
$P\times B_2\cong B_3$, which admits the AHC
\[
\varnothing<\{1,2,3\}>\{1\}<\{1,2\}>\{2\}
<\{2,3\}>\{3\}<\{1,3\}>\varnothing.
\]
We now prove the case $|P|\ge3$. 
First, we suppose that the AHP in $P$ is of the form
\begin{equation}\label{x1-xp}
x_1<x_2>x_3<x_4>\cdots.
\end{equation}

\smallskip
\noindent\textbf{Step 1. Construct four disjoint alternating paths.}
Let $(x_2,x_3,\ldots,x_{|P|-1})$ be an alternating path of $P$ defined in~\eqref{x1-xp}. 
For each $A\in \{\varnothing, \{1\},\{2\}, \{1,2\}\}$, let
\[
I_A=(x_2,A),(x_3,A),\ldots,(x_{|P|-1},A).
\]
Clearly, $I_A$ is an alternating path in $P\times B_2$ from $(x_2,A)$ to $(x_{|P|-1},A)$.
We denote by $\overleftarrow{I_A}$ the path obtained by traversing $I_A$ in reverse order, 
$$
\overleftarrow{I_A}=(x_{|P|-1},A), (x_{|P|-2},A),\ldots,(x_{2},A).
$$
These four paths $I_{\varnothing}, I_{\{1\}},I_{\{2\}}, I_{\{1,2\}}$ are disjoint and traverse
$\{x_2,\ldots,x_{|P|-1}\}\times B_2$.
When $|P|=3$, each $I_A$ consists of a single vertex.

\smallskip
\noindent\textbf{Step 2. The case that $|P|$ is odd.}
Then~\eqref{x1-xp} becomes
$$
x_1<x_2>x_3<x_4>\cdots <x_{|P|-1}>x_{|P|}.
$$
Thus, we construct two joining paths whose endpoints lie in
$\{x_2\}\times B_2$ and whose internal vertices lie in
$\{x_1\}\times B_2$:
\begin{align}
(x_2,\varnothing)
>&(x_1,\varnothing)<(x_2,\{1\}),\label{1-x_1-x_2}\\
(x_2,\{2\})
>(x_1,\{2\})<&(x_1,\{1,2\})
>(x_1,\{1\})<(x_2,\{1,2\}).\label{2-x_1-x_2}
\end{align}
Similarly, we construct two joining paths whose endpoints lie in
$\{x_{|P|-1}\}\times B_2$ and whose internal vertices lie in
$\{x_{|P|}\}\times B_2$:
\begin{align*}
(x_{|P|-1},\varnothing)
>&(x_{|P|},\varnothing)<(x_{|P|-1},\{2\}),\\
(x_{|P|-1},\{1\})
>(x_{|P|},\{1\})<&(x_{|P|},\{1,2\})
>(x_{|P|},\{2\})<(x_{|P|-1},\{1,2\}).
\end{align*}
The four paths visit each vertex $(x_1,A)$ and $(x_{|P|},A)$ 
exactly once. 
See Figure~\ref{fig:b2-odd-joining}.

\begin{figure}[htbp]
\centering
\begin{tikzpicture}[
  scale=0.55,
  x=1cm,y=1cm,
  every node/.style={font=\footnotesize},
  every path/.style={line width=0.8pt},
  path label/.style={fill=white,inner sep=3pt},
  joining label/.style={fill=white,inner sep=2pt,align=left},
  traversal/.style args={#1}{
    postaction={decorate},
    decoration={markings,
      mark=at position #1 with {
        \arrow[red!80!black]{Stealth[length=5pt,width=4pt]}
      }
    }
  }
]
  \coordinate (L0) at (0,0);
  \coordinate (L1) at (0,-1.8);
  \coordinate (L2) at (0,-3.6);
  \coordinate (L3) at (0,-5.4);
  \coordinate (R0) at (3.8,0);
  \coordinate (R1) at (3.8,-1.8);
  \coordinate (R2) at (3.8,-3.6);
  \coordinate (R3) at (3.8,-5.4);

  \draw (L0)--(R0)
    node[midway,path label]
    {$I_\varnothing$};
  \draw[traversal=0.97] (R1)--(L1)
    node[midway,path label]
    {$I_{\{1\}}$};
  \draw[traversal=0.94] (R2)--(L2)
    node[midway,path label]
    {$I_{\{2\}}$};
  \draw (L3)--(R3)
    node[midway,path label]
    {$I_{\{1,2\}}$};

  \draw[traversal=0.75]
    (L1) .. controls (-1.5,-1.8) and (-1.5,0) .. (L0)
    node[pos=0.5,left=3pt,joining label]
    {$(x_1,\varnothing)$};
  \draw[traversal=0.75]
    (L2) .. controls (-1.5,-3.6) and (-1.5,-5.4) .. (L3)
    node[pos=0.5,left=3pt,joining label]
    {$(x_1,\{2\})$
     $<(x_1,\{1,2\})$
     $>(x_1,\{1\})$};

  \draw[traversal=0.18]
    (R0) .. controls (6.3,0) and (6.3,-3.6) .. (R2)
    node[pos=0.5,right=3pt,joining label]
    {$(x_{|P|},\varnothing)$};

  \draw[preaction={draw=white,line width=4pt},traversal=0.18]
    (R3) .. controls (6.1,-5.4) and (6.1,-1.8) .. (R1)
    node[pos=0.5,right=1pt,joining label]
    {$(x_{|P|},\{2\})$
     $<(x_{|P|},\{1,2\})$
     $>(x_{|P|},\{1\})$};

  \foreach \i in {0,1,2,3}{
    \fill (L\i) circle (1.5pt);
    \fill (R\i) circle (1.5pt);
  }
  \node[above=5pt] at (L0) {$x_2$};
  \node[above=5pt] at (R0) {$x_{|P|-1}$};
\end{tikzpicture}

\caption{The connections for odd $|P|$.}


\label{fig:b2-odd-joining}
\end{figure}

\smallskip
\noindent\textbf{Step 3.  The case that $|P|$ is even.}
Then~\eqref{x1-xp} becomes
$$
x_1<x_2>x_3<x_4>\cdots >x_{|P|-1}<x_{|P|}.
$$ 
There are two alternating paths~\eqref{1-x_1-x_2} and~\eqref{2-x_1-x_2} in $\{x_1,x_2\}\times B_2$, the same as those when $|P|$ is odd.







For $(x_{|P|-1},A)$ and $(x_{|P|},A)$,
there are two alternating paths
\begin{align*}
(x_{|P|-1},\{1,2\})
<&(x_{|P|},\{1,2\})>(x_{|P|-1},\{1\}),\\
(x_{|P|-1},\{2\})
<(x_{|P|},\{2\})>&(x_{|P|},\varnothing)
<(x_{|P|},\{1\})>(x_{|P|-1},\varnothing).
\end{align*}
The four paths visit each vertex $(x_1,A)$ and $(x_{|P|},A)$ 
exactly once.


\smallskip
\noindent\textbf{Step 4. This construction forms an AHC.}
The four paths $I_{\varnothing}, I_{\{1\}},I_{\{2\}}, I_{\{1,2\}}$ visit the vertices 
$(x_2,A),\ldots,(x_{|P|-1},A)$ for each $A\in \{\varnothing, \{1\},\{2\}, \{1,2\}\}$. 
The paths in Step 2 or Step 3 visit the vertices  $(x_1,A)$ and $(x_{|P|},A)$. 
Suppose that $|P|$ is odd.
Then
\begin{align*}
(x_1,\varnothing)&\rightarrow I_{\varnothing} \rightarrow (x_{|P|},\varnothing) \rightarrow \overleftarrow{I_{\{2\}}}
\rightarrow (x_1,\{2\})
<(x_1,\{1,2\})>(x_1,\{1\})\\
&\rightarrow I_{\{1,2\}}\rightarrow (x_{|P|},\{2\})<(x_{|P|},\{1,2\})>(x_{|P|},\{1\})\rightarrow \overleftarrow{I_{\{1\}}}
\rightarrow (x_1,\varnothing)
\end{align*}
forms an AHC in $P\times B_2$.
Similarly, we can obtain an AHC in $P\times B_2$ when $|P|$ is even. 

Suppose that the AHP in $P$ is of the form
\begin{equation}\label{x22-xp}
x_1>x_2<x_3>x_4<\cdots.
\end{equation}
Then the dual $P^*$ admits an AHP of the form~\eqref{x1-xp}.
Thus $P^*\times B_2$ admits an AHC.
By Lemma~\ref{lem:basic-properties} (iii),
\[
(P^\ast\times B_2)^\ast
\cong P\times B_2^\ast
\cong P\times B_2
\]
admits an AHC.
This completes the proof.

\label{lem:b3}
Let $P$ be a finite poset with $|P|\ge 2$.
If $P$ admits an AHP, then $P\times B_3$ admits an AHC.

\label{lem:b1}
Let $P$ be a finite poset.
If $P$ admits an AHC, then $P\times B_1$ admits an AHP.

\label{rem:boolean-bound}
	The restriction $r\ge2$ in Theorem~\ref{thm:intro-boolean}(i) is sharp.
	For example, $P=B_1$ admits an AHP, but $P\times B_1\cong B_2$ does not admit an AHC.

\label{lem:c3}
Let $P$ be a finite poset.
If $P$ admits an AHP, then $P\times C_3$ admits an AHC.

\label{lem:chain-extension}
Let $P$ be a finite poset and let $m\ge0$.
If $P\times C_m$ admits an AHP (resp. AHC), then $P\times C_{m+2}$ admits an AHP (resp. AHC).
